import json,re
N='https://blog.naver.com/dong_jin_kim/'
def P(t): return f'<p data-ke-size="size16">{t}</p>'
def H(t): return f'<h3 data-ke-size="size23">{t}</h3>'
def L(no,t): return P('▸ <a href="'+N+no+'">'+t+'</a>')
def TB(rows,head):
    s='<table data-ke-style="style12"><thead><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr></thead><tbody>'
    for r in rows: s+='<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>'
    return s+'</tbody></table>'
def fin(no,t,b,tags,links,tail):
    b+=H('네이버 원문과 함께 보면 좋은 글')
    b+=L(no,'네이버 원문: '+t)
    for n,x in links: b+=L(n,x)
    b+=P(tail); b+=P('문의 010-2882-8165 · 정리 낭만 부동산 분석 플랫폼.')
    json.dump(dict(title=t,body=b,tags=tags),open(f'out/tt_{no}.json','w'),ensure_ascii=False)
    txt=re.sub('<[^>]+>','',b); open(f'out/tt_{no}.txt','w').write(txt); print(no,len(txt))

